'use strict';

// Bundle the whole KMD CLI + Studio into a single CommonJS file
// (build/kmd-bundle.cjs) suitable for Node SEA. Zero deps, no source
// rewriting: every module's source is wrapped VERBATIM in a factory function
// and wired together by a tiny CommonJS loader. Assets that are read from fs
// at runtime (theme.css, Studio UI files) are embedded as strings on
// global.__KMD_ASSETS__ and served through src/assets.js.
//
// Usage: node scripts/bundle.js

const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..');
const ENTRY = 'bin/kmd.js';
const OUT_FILE = path.join(ROOT, 'build', 'kmd-bundle.cjs');

// Runtime fs assets (read via src/assets.js inside the bundle).
const ASSETS = [
  'src/theme.css',
  'src/studio/ui/index.html',
  'src/studio/ui/app.css',
  'src/studio/ui/app.js',
  'src/studio/ui/favicon.svg',
];

// Every require call site in bin/ and src/ uses a single-quoted string
// literal (verified by grepping the tree); accept double quotes too.
const REQUIRE_RE = /require\(\s*(['"])([^'"]+)\1/g;

function readRepo(rel) {
  return fs.readFileSync(path.join(ROOT, rel), 'utf8');
}

// posix normalize of a '/'-joined path: collapse '.' and '..', drop empties.
function normalizePosix(p) {
  const out = [];
  for (const part of p.split('/')) {
    if (!part || part === '.') continue;
    if (part === '..') {
      out.pop();
      continue;
    }
    out.push(part);
  }
  return out.join('/');
}

// Resolve a relative require id against the requiring module's virtual dir;
// implicit '.js' when there is no extension.
function resolveRel(rid, fromId) {
  const fromDir = fromId.split('/').slice(0, -1).join('/');
  let resolved = normalizePosix((fromDir ? fromDir + '/' : '') + rid);
  if (!/\.[a-z0-9]+$/i.test(resolved)) resolved += '.js';
  return resolved;
}

// --- Crawl the module graph from the entry --------------------------------
const modules = new Map(); // id (posix repo-relative) -> source text
const queue = [ENTRY];
while (queue.length > 0) {
  const id = queue.shift();
  if (modules.has(id)) continue;
  let src = readRepo(id);
  if (src.startsWith('#!')) src = src.slice(src.indexOf('\n') + 1); // shebang
  modules.set(id, src);
  REQUIRE_RE.lastIndex = 0;
  let m;
  while ((m = REQUIRE_RE.exec(src)) !== null) {
    const rid = m[2];
    if (!rid.startsWith('.')) continue; // node: builtins / externals pass through
    queue.push(resolveRel(rid, id));
  }
}

// --- Coverage assertion: every *.js under src/ must be reachable ----------
function walkJs(relDir) {
  const out = [];
  for (const e of fs.readdirSync(path.join(ROOT, relDir), { withFileTypes: true })) {
    const rel = relDir + '/' + e.name;
    if (e.isDirectory()) out.push(...walkJs(rel));
    else if (e.isFile() && e.name.endsWith('.js')) out.push(rel);
  }
  return out;
}
const missing = walkJs('src').filter((f) => !modules.has(f) && !ASSETS.includes(f));
if (missing.length > 0) {
  console.error('bundle: files under src/ not reachable from ' + ENTRY + ':');
  for (const f of missing) console.error('  - ' + f);
  process.exit(1);
}

// --- Emit -------------------------------------------------------------------
// NOTE: everything is plain string concatenation; module sources are never
// interpolated into template literals (they contain ${...} sequences).
const LOADER = [
  "'use strict';",
  '/* KMD single-file bundle. Generated by scripts/bundle.js — do not edit. */',
  'const __registry = {};',
  'const __modules = {};',
  'function __normalizePosix(p) {',
  '  const out = [];',
  "  for (const part of p.split('/')) {",
  "    if (!part || part === '.') continue;",
  "    if (part === '..') { out.pop(); continue; }",
  '    out.push(part);',
  '  }',
  "  return out.join('/');",
  '}',
  'function __resolveRel(rid, fromId) {',
  "  const fromDir = fromId.split('/').slice(0, -1).join('/');",
  "  let resolved = __normalizePosix((fromDir ? fromDir + '/' : '') + rid);",
  "  if (!/\\.[a-z0-9]+$/i.test(resolved)) resolved += '.js';",
  '  return resolved;',
  '}',
  'function __require(id) {',
  '  let module = __modules[id];',
  '  if (module) return module.exports;',
  '  const factory = __registry[id];',
  "  if (!factory) throw new Error('module not bundled: ' + id);",
  '  module = { exports: {} };',
  '  __modules[id] = module; // memoize before running (circular-safe)',
  "  const dirname = id.split('/').slice(0, -1).join('/');",
  '  const localRequire = function (rid) {',
  "    if (rid.charAt(0) !== '.') return require(rid); // node: builtins / externals",
  '    return __require(__resolveRel(rid, id));',
  '  };',
  '  factory(localRequire, module, module.exports, dirname, id);',
  '  return module.exports;',
  '}',
  '',
].join('\n');

const chunks = [];
chunks.push(LOADER);
chunks.push('global.__KMD_ASSETS__ = {\n');
chunks.push(
  ASSETS.map((a) => '  ' + JSON.stringify(a) + ': ' + JSON.stringify(readRepo(a))).join(',\n'),
);
chunks.push('\n};\n\n');

for (const [id, src] of modules) {
  chunks.push('__registry[' + JSON.stringify(id) + '] = function(require, module, exports, __dirname, __filename) {\n');
  chunks.push(src);
  if (!src.endsWith('\n')) chunks.push('\n');
  chunks.push('\n};\n\n');
}

// Entry point: bin/kmd.js runs main() at module top level (no require.main
// guard), so loading it through the registry is all it takes.
chunks.push('__require(' + JSON.stringify(ENTRY) + ');\n');

fs.mkdirSync(path.dirname(OUT_FILE), { recursive: true });
fs.writeFileSync(OUT_FILE, chunks.join(''), 'utf8');

const size = fs.statSync(OUT_FILE).size;
console.log('bundled ' + modules.size + ' modules:');
for (const id of modules.keys()) console.log('  ' + id);
console.log('embedded ' + ASSETS.length + ' assets:');
for (const a of ASSETS) console.log('  ' + a);
console.log('-> ' + path.relative(ROOT, OUT_FILE) + ' (' + size + ' bytes)');
